//! End-to-end CLI tests using assert_cmd against committed fixtures.
//!
//! Every pair under tests/fixtures/<name>/{before,after}.kdbx is generated by
//! `cargo run --example gen_fixtures` with fixed UUIDs: each `after`
//! is a clone of `before` with one edit, so entries match by UUID and the diff
//! shows the edit itself (not a remove plus add). tests/fixtures/legacy_kdbx40/
//! is a frozen KDBX 4.0 file. See tests/fixtures/MANIFEST.md.

use assert_cmd::Command;
use predicates::prelude::*;

const PW: &str = "test-password-do-not-use";

fn diff_cmd() -> Command {
    let mut c = Command::cargo_bin("diff-kdbx").unwrap();
    c.env("KDBX_DIFF_PASSWORD", PW);
    c
}

#[test]
fn same_file_diffed_against_itself_exits_zero() {
    diff_cmd()
        .args([
            "tests/fixtures/empty/before.kdbx",
            "tests/fixtures/empty/before.kdbx",
        ])
        .assert()
        .success()
        .stdout(predicate::str::contains("(no changes)"));
}

#[test]
fn add_entry_pair_exits_one_and_reports_added() {
    diff_cmd()
        .args([
            "tests/fixtures/add_entry/before.kdbx",
            "tests/fixtures/add_entry/after.kdbx",
        ])
        .assert()
        .code(1)
        .stdout(predicate::str::contains("+ ENTRY"));
}

/// The textconv dump seals protected fields as keyed fingerprints.
#[test]
fn password_change_seals_by_default() {
    diff_cmd()
        .args(["--textconv", "tests/fixtures/password_change/before.kdbx"])
        .assert()
        .success()
        .stdout(predicate::str::contains("  Password: <sealed:"))
        .stdout(predicate::str::contains("old-password").not());
}

/// --show-secrets reveals the plaintext value of protected fields in the
/// manual dump.
#[test]
fn show_secrets_reveals_plaintext() {
    diff_cmd()
        .args([
            "--show-secrets",
            "--dump",
            "tests/fixtures/password_change/before.kdbx",
        ])
        .assert()
        .success()
        .stdout(predicate::str::contains("old-password"));
}

/// git stores textconv output (its textconv cache is a notes ref that mirror
/// pushes and bundles carry), so --show-secrets with --textconv is refused
/// before anything is opened or written.
#[test]
fn show_secrets_with_textconv_is_refused() {
    diff_cmd()
        .args([
            "--show-secrets",
            "--textconv",
            "tests/fixtures/password_change/before.kdbx",
        ])
        .assert()
        .code(2)
        .stdout(predicate::str::is_empty())
        .stderr(predicate::str::contains(
            "--show-secrets cannot be used with --textconv",
        ));
}

#[test]
fn json_format_produces_valid_json() {
    let out = diff_cmd()
        .args([
            "--format=json",
            "tests/fixtures/add_entry/before.kdbx",
            "tests/fixtures/add_entry/after.kdbx",
        ])
        .output()
        .unwrap();
    let stdout = String::from_utf8(out.stdout).unwrap();
    let _v: serde_json::Value = serde_json::from_str(&stdout).expect("valid JSON");
}

#[test]
fn textconv_emits_dump_for_one_file() {
    diff_cmd()
        .args(["--textconv", "tests/fixtures/add_entry/after.kdbx"])
        .assert()
        .success()
        .stdout(predicate::str::contains("DATABASE"))
        .stdout(predicate::str::contains("ENTRY"));
}

#[test]
fn wrong_password_exits_two() {
    Command::cargo_bin("diff-kdbx")
        .unwrap()
        .env("KDBX_DIFF_PASSWORD", "wrong-password")
        .args([
            "tests/fixtures/empty/before.kdbx",
            "tests/fixtures/empty/after.kdbx",
        ])
        .assert()
        .code(2);
}

#[test]
fn missing_password_for_textconv_fails_closed() {
    Command::cargo_bin("diff-kdbx")
        .unwrap()
        // no KDBX_DIFF_PASSWORD env set
        .env_remove("KDBX_DIFF_PASSWORD")
        .args(["--textconv", "tests/fixtures/empty/before.kdbx"])
        .assert()
        .code(2)
        .stdout(predicate::str::is_empty());
}

/// Run a fixture pair and return (exit code, stdout).
fn pair(name: &str, extra: &[&str]) -> (i32, String) {
    let before = format!("tests/fixtures/{name}/before.kdbx");
    let after = format!("tests/fixtures/{name}/after.kdbx");
    let mut args: Vec<&str> = extra.to_vec();
    args.push(&before);
    args.push(&after);
    let out = diff_cmd().args(&args).output().unwrap();
    (
        out.status.code().expect("exited normally"),
        String::from_utf8(out.stdout).unwrap(),
    )
}

/// Opening and re-saving touches only access time and usage count, which
/// default mode suppresses: no changes, exit 0, and the summary counts them.
#[test]
fn noisy_resave_default_reports_no_changes() {
    let (code, out) = pair("noisy_resave", &[]);
    assert_eq!(code, 0, "{out}");
    assert!(out.contains("(no changes)"), "{out}");
    assert!(out.contains("suppressed 6"), "{out}");
}

/// --strict turns suppression off: the same pair reports the timestamp noise
/// and exits 1.
#[test]
fn strict_disables_suppression() {
    let (code, out) = pair("noisy_resave", &["--strict"]);
    assert_eq!(code, 1, "{out}");
    assert!(!out.contains("(no changes)"), "{out}");
    assert!(out.contains("~ LastAccessTime: "), "{out}");
    assert!(out.contains("~ UsageCount: 0 -> 1"), "{out}");
}

/// Matched UUIDs make a password edit a sealed property change, with neither
/// plaintext shown.
#[test]
fn password_change_diff_is_masked_modified() {
    let (code, out) = pair("password_change", &[]);
    assert_eq!(code, 1, "{out}");
    assert!(out.contains("~ ENTRY \"/Personal/Bank\""), "{out}");
    assert!(
        predicate::str::is_match(r"~ Password: <sealed:[0-9a-f]{8}> -> <sealed:[0-9a-f]{8}>\n")
            .unwrap()
            .eval(&out),
        "{out}"
    );
    assert!(!out.contains("old-password") && !out.contains("new-password"));
    assert!(
        !out.contains("+ ENTRY") && !out.contains("- ENTRY"),
        "{out}"
    );
}

#[test]
fn password_change_diff_show_secrets_reveals_both_values() {
    let (_, out) = pair("password_change", &["--show-secrets"]);
    assert!(
        out.contains("~ Password: \"old-password\" (protected) -> \"new-password\" (protected)"),
        "{out}"
    );
}

#[test]
fn remove_entry_reports_removed() {
    let (code, out) = pair("remove_entry", &[]);
    assert_eq!(code, 1);
    assert!(out.contains("- ENTRY \"/Personal/Email\""), "{out}");
}

/// A move is one record with its origin, and no property noise (the
/// location-changed time is suppressed).
#[test]
fn move_entry_reports_single_move() {
    let (code, out) = pair("move_entry", &[]);
    assert_eq!(code, 1);
    assert!(
        out.contains("~ ENTRY \"/Personal/VPN\" (moved from \"/Work/VPN\")\n"),
        "{out}"
    );
    assert!(out.contains("properties 0,"), "{out}");
}

/// Renaming a group is a Name change on the group and no cascading entry
/// moves.
#[test]
fn rename_group_reports_rename_without_cascade() {
    let (code, out) = pair("rename_group", &[]);
    assert_eq!(code, 1);
    assert!(
        out.contains("~ GROUP \"/Office/\"\n  ~ Name: \"Work\" -> \"Office\"\n"),
        "{out}"
    );
    assert!(out.contains("entries +0/-0/~0"), "{out}");
}

#[test]
fn tag_diff_reports_added_tag() {
    let (_, out) = pair("tag_diff", &[]);
    assert!(out.contains("  + Tag[\"finance\"]\n"), "{out}");
}

#[test]
fn attachment_change_reports_modified_and_added() {
    let (_, out) = pair("attachment_change", &[]);
    assert!(
        out.contains("  ~ Attachment[\"recovery.txt\"]: <sealed:"),
        "{out}"
    );
    assert!(
        out.contains("  + Attachment[\"statement.pdf\"]: <sealed:"),
        "{out}"
    );
}

/// A rotated TOTP seed in a protected custom field is reported, sealed, in
/// both the diff and the textconv dump (where it was once invisible).
#[test]
fn custom_field_change_is_reported_masked() {
    let (_, out) = pair("custom_field", &[]);
    assert!(
        predicate::str::is_match(r#"~ "otp": <sealed:[0-9a-f]{8}> -> <sealed:[0-9a-f]{8}>"#)
            .unwrap()
            .eval(&out),
        "{out}"
    );
    assert!(!out.contains("otpauth://"), "{out}");
    for side in ["before", "after"] {
        let dump = diff_cmd()
            .args([
                "--textconv",
                &format!("tests/fixtures/custom_field/{side}.kdbx"),
            ])
            .output()
            .unwrap();
        let dump = String::from_utf8(dump.stdout).unwrap();
        assert!(dump.contains("  \"otp\": <sealed:"), "{dump}");
    }
}

#[test]
fn history_grew_reports_edit_and_history() {
    let (_, out) = pair("history_grew", &[]);
    assert!(
        out.contains("~ URL: \"https://bank.example\" -> \"https://bank.example/login\""),
        "{out}"
    );
    assert!(
        out.contains("  + History[2026-01-01T09:00:00Z].URL: \"https://bank.example\"\n"),
        "{out}"
    );
}

/// keepass 0.13+ can only write KDBX 4.1, so the generated fixtures are 4.1.
/// This frozen 4.0 file keeps read coverage for the format most vaults use.
#[test]
fn legacy_kdbx40_is_readable() {
    diff_cmd()
        .args(["--textconv", "tests/fixtures/legacy_kdbx40/vault.kdbx"])
        .assert()
        .success()
        .stdout(predicate::str::contains("  Version: 4.0\n"))
        .stdout(predicate::str::contains("ENTRY \"/Test Entry\" [uuid:"));
}

#[test]
fn cross_version_diff_warns() {
    diff_cmd()
        .args([
            "tests/fixtures/legacy_kdbx40/vault.kdbx",
            "tests/fixtures/add_entry/before.kdbx",
        ])
        .assert()
        .code(1)
        .stdout(predicate::str::contains(
            "warning: KDBX version differs: 4.0 -> 4.1",
        ));
}

/// A moved-and-edited entry is one record, counted once.
#[test]
fn move_and_edit_is_one_record() {
    let (code, out) = pair("move_and_edit", &[]);
    assert_eq!(code, 1);
    assert!(
        out.contains(
            "~ ENTRY \"/Personal/VPN\" (moved from \"/Work/VPN\")\n  ~ URL: \"https://vpn.example\" -> \"https://vpn2.example\"\n"
        ),
        "{out}"
    );
    assert!(out.contains("entries +0/-0/~1 (1 moved)"), "{out}");
    assert_eq!(out.matches("ENTRY").count(), 1, "{out}");
}

/// A moved-and-renamed group is one record; its entries ride along.
#[test]
fn move_and_rename_group_is_one_record() {
    let (code, out) = pair("move_and_rename_group", &[]);
    assert_eq!(code, 1);
    assert!(
        out.contains("~ GROUP \"/Personal/Office/\" (moved from \"/Work/\")\n  ~ Name: \"Work\" -> \"Office\"\n"),
        "{out}"
    );
    assert!(out.contains("entries +0/-0/~0 (0 moved)"), "{out}");
}

/// A protected Title stays plain: it is the entry's address.
#[test]
fn protected_title_stays_an_address() {
    let (_, out) = pair("protected_title", &[]);
    assert!(
        out.contains("~ ENTRY \"/Personal/Bank\"\n  ~ Title: \"Bank\" -> \"Bank\" (protected)\n"),
        "{out}"
    );
    diff_cmd()
        .args(["--textconv", "tests/fixtures/protected_title/after.kdbx"])
        .assert()
        .success()
        .stdout(predicate::str::contains("ENTRY \"/Personal/Bank\" [uuid:"))
        .stdout(predicate::str::contains("  Title: \"Bank\" (protected)\n"));
}

/// Multi-line Notes that imitate structural lines cannot forge one, in the
/// diff or in the dump, and still diff line by line.
#[test]
fn notes_cannot_forge_structural_lines() {
    let (_, out) = pair("notes_injection", &[]);
    let dump = String::from_utf8(
        diff_cmd()
            .args(["--textconv", "tests/fixtures/notes_injection/after.kdbx"])
            .output()
            .unwrap()
            .stdout,
    )
    .unwrap();
    for (text, structural) in [
        (&out, ["+ ", "- ", "~ "]),
        (&dump, ["GROUP", "ENTRY", "DATA"]),
    ] {
        let forged: Vec<&str> = text
            .lines()
            .filter(|l| structural.iter().any(|s| l.starts_with(s)) && l.contains("Forged"))
            .collect();
        assert!(forged.is_empty(), "{forged:?}\n{text}");
    }
    assert!(out.contains("      | + ENTRY /Forged\n"), "{out}");
    assert!(dump.contains("    | + ENTRY /Forged\n"), "{dump}");
}

/// Turning protection off is visible even when the value is unchanged.
#[test]
fn protection_toggle_is_reported() {
    let (code, out) = pair("protection_toggle", &[]);
    assert_eq!(code, 1);
    assert!(
        predicate::str::is_match(
            r"  ~ Password: <sealed:([0-9a-f]{8})> -> <sealed:([0-9a-f]{8})> \(unprotected\)\n"
        )
        .unwrap()
        .eval(&out),
        "{out}"
    );
    assert!(
        out.contains("  ~ \"otp\": <sealed:") && out.contains("-> \"otpauth://totp/Email?secret="),
        "{out}"
    );
}

#[test]
fn override_url_is_reported() {
    let (_, out) = pair("override_url", &[]);
    assert!(
        out.contains("  + OverrideURL: \"cmd://firefox --private-window {URL}\"\n"),
        "{out}"
    );
}

/// At the history cap, a new edit adds one history item and trims the
/// oldest: one item removed, one added, nothing else in history.
#[test]
fn history_at_cap_is_one_removal_and_one_addition() {
    let (_, out) = pair("history_at_cap", &[]);
    let history: Vec<&str> = out.lines().filter(|l| l.contains("History[")).collect();
    assert!(!history.is_empty());
    assert!(
        history
            .iter()
            .all(|l| l.starts_with("  - History[2026-01-01T09:00:00Z].")
                || l.starts_with("  + History[2026-01-04T09:00:00Z].")),
        "{out}"
    );
    assert!(out.contains("  + History[2026-01-04T09:00:00Z].URL: \"https://bank.example/v4\"\n"));
}

/// A recycle-bin UUID naming the root does not hide the vault.
#[test]
fn recycle_bin_naming_the_root_hides_nothing() {
    let (code, out) = pair("recycle_bin_root", &[]);
    assert_eq!(code, 1);
    assert!(
        out.contains("~ ENTRY \"/Personal/Bank\"\n  ~ UserName: \"alice\" -> \"bob\"\n"),
        "{out}"
    );
}

/// Moving an entry to the recycle bin reads as a removal by default, and as
/// a move with --include-recycle-bin.
#[test]
fn trashing_an_entry() {
    let (_, out) = pair("trash_entry", &[]);
    assert!(out.contains("- ENTRY \"/Personal/Email\"\n"), "{out}");
    let (_, out) = pair("trash_entry", &["--include-recycle-bin"]);
    assert!(
        out.contains("~ ENTRY \"/Recycle Bin/Email\" (moved from \"/Personal/Email\")\n"),
        "{out}"
    );
}

/// A weakened KDF is reported as header changes and typed warnings.
#[test]
fn kdf_downgrade_warns() {
    let (code, out) = pair("kdf_downgrade", &[]);
    assert_eq!(code, 1);
    assert!(
        out.contains("warning: KDF weakened: memory lowered from 2097152 to 1048576 bytes\n"),
        "{out}"
    );
    assert!(
        out.contains("warning: KDF weakened: iterations lowered from 4 to 2\n"),
        "{out}"
    );
    assert!(
        out.contains("DATABASE\n  ~ KdfMemory: 2097152 -> 1048576\n  ~ KdfIterations: 4 -> 2\n"),
        "{out}"
    );
    let json = diff_cmd()
        .args([
            "--format=json",
            "tests/fixtures/kdf_downgrade/before.kdbx",
            "tests/fixtures/kdf_downgrade/after.kdbx",
        ])
        .output()
        .unwrap();
    let v: serde_json::Value = serde_json::from_slice(&json.stdout).unwrap();
    assert_eq!(v["warnings"][0]["kind"], "kdf_weakened");
    assert_eq!(v["warnings"][0]["aspect"], "memory_lowered");
    // Both vaults cost less than the floor, so the key derives at the floor.
    assert_eq!(
        v["fingerprint_key"]["params"],
        "argon2id$v=19$m=65536,t=3,p=1"
    );
}

/// A vault without a password opens with its key file alone.
#[test]
fn keyfile_only_vault_opens_with_its_key_file() {
    let kf = "tests/fixtures/keyfile_only/vault.key";
    let vault = "tests/fixtures/keyfile_only/vault.kdbx";
    Command::cargo_bin("diff-kdbx")
        .unwrap()
        .env_remove("KDBX_DIFF_PASSWORD")
        .args(["--key-file", kf, "--textconv", vault])
        .assert()
        .success()
        .stdout(predicate::str::contains("ENTRY \"/Personal/Bank\" [uuid:"));
    Command::cargo_bin("diff-kdbx")
        .unwrap()
        .env("KDBX_DIFF_PASSWORD", PW)
        .args(["--no-password", "--key-file", kf, vault, vault])
        .assert()
        .code(0)
        .stdout(predicate::str::contains("(no changes)"));
}
